// Module statuses, key: the order id. Owns R7.2 (§2 orders.setStatus): the only writer of order and fulfilment
// statuses. The system does not check transitions, so this module does: forward only, each status at most once,
// and a late or repeated request changes nothing. Effects: orders.setStatus (keys `order.<status>`,
// `f.<fulfilmentId>.<status>`). Always return `output`.
//
// state: { order: status|null, fulfilments: { [fulfilmentId]: status } }   (null until init)

const ORDER_NEXT = {
  pending: ['customerActionRequired', 'processing', 'cancelled', 'timedOut'],
  customerActionRequired: ['processing', 'cancelled', 'timedOut'],
  processing: ['completed', 'failed', 'cancelled'],
  completed: [], failed: [], cancelled: [], timedOut: [],
};

const FULFILMENT_NEXT = {
  unavailable: ['cancelled'],
  pending: ['processing', 'failed', 'cancelled'],
  processing: ['dispatched', 'failed', 'cancelled'],
  dispatched: ['completed'],
  completed: [], failed: [], cancelled: [],
};

export function step(input, ctx) {
  switch (input.op) {
    case 'init': return init(input, ctx);
    case 'set': return set(input, ctx);
    case 'get': return { output: view(ctx.state) };
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`statuses: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  // Results of orders.setStatus carry no decision of their own: a status is what we asked for, and the platform
  // retries it with the same key. Nothing to do.
  return { output: view(ctx.state) };
}

function view(state) {
  if (!state) return { applied: false, order: null, fulfilments: {}, busy: false };
  return { applied: false, order: state.order, fulfilments: { ...state.fulfilments }, busy: false };
}

function init(input, ctx) {
  // The order is recorded by orders.create (intake): order pending, each fulfilment pending or unavailable (§2).
  // Only record it here; no effect (R7.2).
  const fulfilments = {};
  for (const f of input.fulfilments) fulfilments[f.fulfilmentId] = f.location === null ? 'unavailable' : 'pending';
  const state = { order: 'pending', fulfilments };
  return { output: { ...view(state), applied: true }, state };
}

function set(input, ctx) {
  const state = ctx.state;
  if (!state) return { output: view(null) };                       // before init: refused (R4.1)
  const orderId = input.orderId;
  const target = input.fulfilmentId === null ? null : input.fulfilmentId;
  const current = target === null ? state.order : state.fulfilments[target];
  if (current === undefined) return { output: view(state) };        // unknown fulfilment: nothing
  const next = target === null ? ORDER_NEXT : FULFILMENT_NEXT;
  const emit = [];
  let at = current;
  if (input.afterStatus && input.afterStatus !== at && (next[at] ?? []).includes(input.afterStatus)) {
    emit.push(input.afterStatus);
    at = input.afterStatus;
  }
  if (at !== input.status && (next[at] ?? []).includes(input.status)) emit.push(input.status);
  else if (emit.length === 0) return { output: view(state) };        // a repeat, a backward move or a skip: nothing
  const effects = [];
  let prev = null;
  for (const status of emit) {
    const key = target === null ? `order.${status}` : `f.${target}.${status}`;
    const e = { key, system: 'orders', op: 'setStatus', args: { orderId, fulfilmentId: target, status } };
    if (prev) e.after = prev;
    effects.push(e);
    prev = key;
  }
  const newState = { order: state.order, fulfilments: { ...state.fulfilments } };
  if (target === null) newState.order = emit.at(-1);
  else newState.fulfilments[target] = emit.at(-1);
  return { output: { ...view(newState), applied: true }, state: newState, effects };
}

function resume(input, ctx) {
  // §3.5: a migrated order: take its statuses from the records as they stand.
  const r = input.records ?? {};
  const fulfilments = {};
  for (const f of r.fulfilments ?? []) fulfilments[f.fulfilmentId] = f.status;
  const state = { order: r.order ?? 'pending', fulfilments };
  return { output: { ...view(state), applied: false }, state };
}
// Module notices, key: the order id. Owns §4.8: the only sender of notify.send. Each required notification is sent
// exactly once (one key per notice, kept in state). Effects: notify.send:<template> (keys `<template>.<about>`, or
// `cancel-refused.<eventId>`). Always return `output`.
//
// state: { customerId, sent: [notice key, ...] }

const TEMPLATES = ['action-required', 'order-cancelled', 'order-timed-out', 'fulfilment-failed', 'cancel-refused', 'unknown-order'];

const TEXT = {
  'action-required': 'Some items of your order are unavailable. Reply to amend the order or to cancel it.',
  'order-cancelled': 'Your order has been cancelled.',
  'order-timed-out': 'Your order has timed out because no action was taken on the unavailable items.',
  'fulfilment-failed': 'One part of your order could not be fulfilled and has been cancelled.',
  'cancel-refused': 'Your order can no longer be cancelled because it has already been collected for shipping.',
  'unknown-order': 'We could not find an order with that reference.',
};

// Files arrive as raw text: parse a JSON file (or pass a parsed value through).
function fileJson(files, path) {
  const v = files?.[path];
  return typeof v === 'string' ? JSON.parse(v) : v ?? null;
}

export function step(input, ctx) {
  switch (input.op) {
    case 'init': return init(input, ctx);
    case 'send': return send(input, ctx);
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`notices: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  // notify.send results need no action: the platform retries with the same key.
  return { output: { sent: ctx.state?.sent?.length ?? 0, busy: false } };
}

function init(input, ctx) {
  const state = { customerId: input.customerId, sent: ctx.state?.sent ?? [] };
  return { output: { sent: state.sent.length, busy: false }, state };
}

function send(input, ctx) {
  const state = ctx.state ?? { customerId: null, sent: [] };
  if (!TEMPLATES.includes(input.template)) throw new Error(`notices: unknown template ${input.template}`);
  const local = input.occurrence ? `${input.template}.${input.occurrence}` : `${input.template}.${input.about}`;
  if (state.sent.includes(local)) return { output: { sent: state.sent.length, busy: false } };
  const to = input.to ?? customerEmail(ctx.files, state.customerId);
  const e = {
    key: local,
    system: 'notify',
    op: 'send',
    args: { to, about: input.about, template: input.template, text: input.text ?? TEXT[input.template] },
  };
  const sent = [...state.sent, local];
  return { output: { sent: sent.length, busy: false }, state: { ...state, sent }, effects: [e] };
}

function resume(input, ctx) {
  // §3.5: the notices already sent for this order, from the records.
  const state = { customerId: input.customerId ?? null, sent: [...(input.sent ?? [])] };
  return { output: { sent: state.sent.length, busy: false }, state };
}

// The customer's email from master/customers.json (shape read defensively; see tests).
export function customerEmail(files, customerId) {
  const data = fileJson(files, 'master/customers.json');
  if (!data || customerId === null || customerId === undefined) return null;
  const rows = Array.isArray(data) ? data : Array.isArray(data.customers) ? data.customers : Object.values(data);
  for (const c of rows) {
    if (c && (c.customerId === customerId || c.id === customerId) && typeof c.email === 'string') return c.email;
  }
  const direct = data[customerId];
  return direct && typeof direct.email === 'string' ? direct.email : null;
}
// Module order-progress, key: the order id. Owns R4.1 (ready -> processing statuses) and R4.5 (the order outcome
// once every fulfilment has ended). It emits no effects itself: statuses are set through the statuses module.
// Always return `output`.
//
// state: { state: 'processing'|'ended'|'stopped', outcome: null|'completed'|'failed'|'cancelled', at }

const ENDED = ['completed', 'failed', 'cancelled'];

export function step(input, ctx) {
  switch (input.op) {
    case 'ready': return ready(input, ctx);
    case 'ended': return ended(input, ctx);
    case 'stop': return stop(input, ctx);
    case 'resume': return resume(input, ctx);
  }
  throw new Error(`order-progress: unknown op ${input.op}`);
}

export function onEvent(event, ctx) {
  // This module causes no effects of its own that report back; the statuses module handles its results.
  return { output: view(ctx.state) };
}

function view(state) {
  if (!state) return { state: 'idle', outcome: null, at: null };
  return { state: state.state, outcome: state.outcome, at: state.at };
}

function ready(input, ctx) {
  // R4.1: once, at the ready instant t: the order and every available fulfilment to processing.
  if (ctx.state) return { output: view(ctx.state) };
  ctx.call('statuses', input.orderId, { op: 'set', orderId: input.orderId, fulfilmentId: null, status: 'processing' });
  for (const f of input.fulfilments) {
    if (!f.available) continue;
    ctx.call('statuses', input.orderId, { op: 'set', orderId: input.orderId, fulfilmentId: f.fulfilmentId, status: 'processing' });
  }
  const state = { state: 'processing', outcome: null, at: input.at };
  return { output: view(state), state };
}

function ended(input, ctx) {
  // R4.5: when every fulfilment is completed, failed or cancelled, the order is completed if one completed, else
  // failed if one failed, else cancelled. Done once, at the event that ended the last fulfilment.
  if (!ctx.state || ctx.state.state !== 'processing') return { output: view(ctx.state) };
  const view_ = ctx.call('statuses', input.orderId, { op: 'get', orderId: input.orderId });
  const statuses = Object.values(view_.fulfilments);
  if (statuses.length === 0 || !statuses.every(s => ENDED.includes(s))) return { output: view(ctx.state) };
  const outcome = statuses.includes('completed') ? 'completed' : statuses.includes('failed') ? 'failed' : 'cancelled';
  ctx.call('statuses', input.orderId, { op: 'set', orderId: input.orderId, fulfilmentId: null, status: outcome });
  const state = { state: 'ended', outcome, at: input.at };
  return { output: view(state), state };
}

function stop(input, ctx) {
  // R6.2: a counted customer cancel stops the order; the order then ends cancelled by R6.2, not by R4.5 (pitfall 5).
  if (!ctx.state) return { output: view({ state: 'stopped', outcome: null, at: input.at }), state: { state: 'stopped', outcome: null, at: input.at } };
  if (ctx.state.state === 'processing') {
    const state = { state: 'stopped', outcome: null, at: input.at };
    return { output: view(state), state };
  }
  return { output: view(ctx.state) };
}

function resume(input, ctx) {
  // §3.5: continue from the records: an order already processing or already ended stays so.
  const s = input.records ?? {};
  if (!s.state) return { output: view(ctx.state) };
  const state = { state: s.state, outcome: s.outcome ?? null, at: s.at ?? null };
  return { output: view(state), state };
}

